"""Incident operations starter application."""

from .memory_store import MemoryIncidentStore
from .models import Incident, IncidentStatus, Severity
from .service import IncidentService

__all__ = [
    "Incident",
    "IncidentService",
    "IncidentStatus",
    "MemoryIncidentStore",
    "Severity",
]

"""Core values used by the starter application."""

from __future__ import annotations

from dataclasses import dataclass, replace
from enum import StrEnum


class Severity(StrEnum):
    P1 = "P1"
    P2 = "P2"
    P3 = "P3"
    P4 = "P4"


class IncidentStatus(StrEnum):
    OPEN = "open"
    ACKNOWLEDGED = "acknowledged"
    RESOLVED = "resolved"


@dataclass(frozen=True, slots=True)
class Incident:
    id: str
    title: str
    severity: Severity
    status: IncidentStatus
    owner: str | None
    created_at: float
    updated_at: float

    def changed(self, **values: object) -> "Incident":
        return replace(self, **values)

"""The original process-local incident store."""

from __future__ import annotations

import time
import uuid
from collections.abc import Callable

from .models import Incident, IncidentStatus, Severity


class MemoryIncidentStore:
    def __init__(self, clock: Callable[[], float] = time.time) -> None:
        self._clock = clock
        self._incidents: dict[str, Incident] = {}

    def create(self, title: str, severity: Severity | str) -> Incident:
        now = self._clock()
        incident = Incident(
            id=str(uuid.uuid4()),
            title=title,
            severity=Severity(severity),
            status=IncidentStatus.OPEN,
            owner=None,
            created_at=now,
            updated_at=now,
        )
        self._incidents[incident.id] = incident
        return incident

    def get(self, incident_id: str) -> Incident | None:
        return self._incidents.get(incident_id)

    def list(self) -> list[Incident]:
        return sorted(self._incidents.values(), key=lambda item: item.created_at)

    def save(self, incident: Incident) -> Incident:
        if incident.id not in self._incidents:
            raise KeyError(incident.id)
        self._incidents[incident.id] = incident
        return incident

"""Business operations for the original in-memory application."""

from __future__ import annotations

import time
from collections.abc import Callable

from .memory_store import MemoryIncidentStore
from .models import Incident, IncidentStatus, Severity


class IncidentService:
    def __init__(
        self,
        store: MemoryIncidentStore | None = None,
        clock: Callable[[], float] = time.time,
    ) -> None:
        self.store = store or MemoryIncidentStore(clock=clock)
        self.clock = clock

    def create(self, title: str, severity: Severity | str) -> Incident:
        if not title.strip():
            raise ValueError("title is required")
        return self.store.create(title.strip(), severity)

    def list(self) -> list[Incident]:
        return self.store.list()

    def assign(self, incident_id: str, owner: str) -> Incident:
        incident = self._required(incident_id)
        return self.store.save(
            incident.changed(owner=owner.strip() or None, updated_at=self.clock())
        )

    def acknowledge(self, incident_id: str) -> Incident:
        incident = self._required(incident_id)
        if incident.status is IncidentStatus.RESOLVED:
            raise ValueError("a resolved incident cannot be acknowledged")
        return self.store.save(
            incident.changed(
                status=IncidentStatus.ACKNOWLEDGED,
                updated_at=self.clock(),
            )
        )

    def resolve(self, incident_id: str) -> Incident:
        incident = self._required(incident_id)
        return self.store.save(
            incident.changed(status=IncidentStatus.RESOLVED, updated_at=self.clock())
        )

    def _required(self, incident_id: str) -> Incident:
        incident = self.store.get(incident_id)
        if incident is None:
            raise KeyError(incident_id)
        return incident

"""Small standard-library HTTP server for the starter interface."""

from __future__ import annotations

import json
from dataclasses import asdict
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from .service import IncidentService


STATIC_DIR = Path(__file__).with_name("static")


def json_value(value: object) -> object:
    if hasattr(value, "value"):
        return value.value
    raise TypeError(f"cannot encode {type(value).__name__}")


def create_server(
    service: IncidentService,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop."""

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            if self.path == "/api/incidents":
                self._json(200, [asdict(item) for item in service.list()])
                return
            if self.path in {"/", "/index.html"}:
                self._file("index.html", "text/html; charset=utf-8")
                return
            if self.path == "/app.js":
                self._file("app.js", "text/javascript; charset=utf-8")
                return
            if self.path == "/styles.css":
                self._file("styles.css", "text/css; charset=utf-8")
                return
            self.send_error(404)

        def do_POST(self) -> None:
            if self.path != "/api/incidents":
                self.send_error(404)
                return
            try:
                payload = self._body()
                incident = service.create(payload["title"], payload["severity"])
            except (KeyError, ValueError, json.JSONDecodeError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(201, asdict(incident))

        def _body(self) -> dict:
            length = int(self.headers.get("Content-Length", "0"))
            return json.loads(self.rfile.read(length))

        def _file(self, name: str, content_type: str) -> None:
            body = (STATIC_DIR / name).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=json_value).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    return ThreadingHTTPServer((host, port), Handler)
"""Command line entry point for the starter application."""

from __future__ import annotations

import argparse

from .service import IncidentService
from .web import create_server


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser()
    subcommands = result.add_subparsers(dest="command", required=True)
    serve = subcommands.add_parser("serve")
    serve.add_argument("--host", default="127.0.0.1")
    serve.add_argument("--port", type=int, default=8080)
    return result


def main() -> int:
    args = parser().parse_args()
    if args.command == "serve":
        server = create_server(IncidentService(), args.host, args.port)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from incident_ops import IncidentService, IncidentStatus, MemoryIncidentStore, Severity


def test_create_assign_acknowledge_and_resolve() -> None:
    ticks = iter([10.0, 11.0, 12.0, 13.0])
    clock = lambda: next(ticks)
    service = IncidentService(MemoryIncidentStore(clock), clock)

    incident = service.create("Database errors", Severity.P1)
    assert incident.status is IncidentStatus.OPEN
    assert service.assign(incident.id, "Rajiv").owner == "Rajiv"
    assert service.acknowledge(incident.id).status is IncidentStatus.ACKNOWLEDGED
    assert service.resolve(incident.id).status is IncidentStatus.RESOLVED


def test_list_uses_creation_order_and_returns_immutable_values() -> None:
    ticks = iter([20.0, 10.0])
    store = MemoryIncidentStore(lambda: next(ticks))
    later = store.create("Later", "P3")
    earlier = store.create("Earlier", "P2")

    assert [item.id for item in store.list()] == [earlier.id, later.id]
    assert store.get(later.id) == later


def test_rejects_blank_title_and_acknowledging_resolved_incident() -> None:
    service = IncidentService(clock=lambda: 1.0)
    try:
        service.create(" ", "P2")
    except ValueError as exc:
        assert "title" in str(exc)
    else:
        raise AssertionError("blank title should fail")

    incident = service.create("Network issue", "P2")
    service.resolve(incident.id)
    try:
        service.acknowledge(incident.id)
    except ValueError as exc:
        assert "resolved" in str(exc)
    else:
        raise AssertionError("resolved incident should not be acknowledged")
