}

.filter-label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; font-weight: 600; color: var(--muted); }
.toolbar select, .toolbar input, .toolbar button {
  box-sizing: border-box;
  min-height: 38px;
  padding: 6px 10px;
  font: inherit;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: white;
  color: var(--text);
}

.feedback {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 14px;
