.detail-header { margin-bottom: 12px; }
.detail-header h2 { margin: 0 0 4px; font-size: 18px; }
.detail-meta { display: flex; flex-wrap: wrap; gap: 6px; font-size: 12px; color: var(--muted); }
.detail-meta span { background: #f0f4fa; padding: 2px 8px; border-radius: 6px; }

.controls {
  display: flex;
