const app = document.getElementById("incident-app");
const list = document.getElementById("incident-list");
const detail = document.getElementById("incident-detail");
const feedback = document.getElementById("feedback");
const statusFilter = document.getElementById("status-filter");
const severityFilter = document.getElementById("severity-filter");
const escalateBtn = document.getElementById("escalate-btn");
const statTotal = document.getElementById("stat-total");
const statOpen = document.getElementById("stat-open");
const statAck = document.getElementById("stat-ack");
const statResolved = document.getElementById("stat-resolved");

const state = {
  incidents: [],
  selectedId: null,
  filters: { status: "", severity: "" },
  feedback: "",
};

function setFeedback(message, kind) {
  state.feedback = message;
  feedback.textContent = message;
  feedback.className = "feedback" + (kind ? " " + kind : "");
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.filters.status) params.set("status", state.filters.status);
  if (state.filters.severity) params.set("severity", state.filters.severity);
  const qs = params.toString();
  const url = "/api/incidents" + (qs ? "?" + qs : "");
  try {
    const response = await fetch(url);
    state.incidents = await response.json();
    renderList();
    await refreshSummary();
    if (state.selectedId) {
      await selectIncident(state.selectedId);
    }
  } catch (err) {
    setFeedback("Failed to load incidents: " + err.message, "error");
  }
}

async function refreshSummary() {
  try {
    const response = await fetch("/api/summary");
    const summary = await response.json();
    statTotal.textContent = summary.total;
    statOpen.textContent = summary.by_status ? summary.by_status["open"] || 0 : 0;
    statAck.textContent = summary.by_status ? summary.by_status["acknowledged"] || 0 : 0;
    statResolved.textContent = summary.by_status ? summary.by_status["resolved"] || 0 : 0;
  } catch (err) {
    // Summary is best-effort
  }
}

function renderList() {
  list.replaceChildren(...state.incidents.map(renderIncidentRow));
}

function renderIncidentRow(incident) {
  const row = document.createElement("div");
  row.setAttribute("data-testid", "incident-row");
  row.className = "incident-row" + (incident.id === state.selectedId ? " selected" : "");
  row.dataset.id = incident.id;

  const badge = document.createElement("span");
  badge.className = "sev-badge sev-" + incident.severity;
  badge.textContent = incident.severity;

  const info = document.createElement("div");
  info.style.overflow = "hidden";

  const title = document.createElement("div");
  title.className = "row-title";
  title.textContent = incident.title;

  const meta = document.createElement("div");
  meta.className = "row-meta";
  const pill = document.createElement("span");
  pill.className = "status-pill status-" + incident.status;
  pill.textContent = incident.status;
  meta.appendChild(pill);
  if (incident.owner) {
    const ownerSpan = document.createElement("span");
    ownerSpan.textContent = "Owner: " + incident.owner;
    meta.appendChild(ownerSpan);
  }
  const alertSpan = document.createElement("span");
  alertSpan.textContent = "Alerts: " + incident.alert_count;
  meta.appendChild(alertSpan);

  info.appendChild(title);
  info.appendChild(meta);

  const esc = document.createElement("div");
  esc.style.fontSize = "11px";
  esc.style.color = "#6b7a90";
  esc.textContent = "Esc: " + incident.escalation_level;

  row.appendChild(badge);
  row.appendChild(info);
  row.appendChild(esc);
  row.addEventListener("click", () => selectIncident(incident.id));
  return row;
}

async function selectIncident(id) {
  state.selectedId = id;
  renderList();
  try {
    const response = await fetch("/api/incidents/" + encodeURIComponent(id));
    if (!response.ok) {
      detail.innerHTML = '<p class="placeholder">Incident not found.</p>';
      return;
    }
    const data = await response.json();
    renderDetail(data);
  } catch (err) {
    setFeedback("Failed to load incident: " + err.message, "error");
  }
}

function renderDetail(data) {
  detail.innerHTML = "";
  const header = document.createElement("div");
  header.className = "detail-header";

  const h2 = document.createElement("h2");
  h2.textContent = data.title;
  header.appendChild(h2);

  const meta = document.createElement("div");
  meta.className = "detail-meta";
  const fields = [
    ["ID", data.id],
    ["Severity", data.severity],
    ["Status", data.status],
    ["Owner", data.owner || "—"],
    ["Alerts", data.alert_count],
    ["Version", data.version],
    ["Escalation", data.escalation_level],
    ["SLA", new Date(data.sla_deadline * 1000).toLocaleString()],
  ];
  for (const [label, val] of fields) {
    const span = document.createElement("span");
    span.textContent = label + ": " + val;
    meta.appendChild(span);
  }
  header.appendChild(meta);
  detail.appendChild(header);

  // Controls
  const controls = document.createElement("div");
  controls.className = "controls";

  const ownerLabel = document.createElement("label");
  ownerLabel.textContent = "Owner";
  const ownerInput = document.createElement("input");
  ownerInput.setAttribute("data-testid", "owner-input");
  ownerInput.setAttribute("type", "text");
  ownerInput.value = data.owner || "";
  ownerLabel.appendChild(ownerInput);
  controls.appendChild(ownerLabel);

  const ackBtn = document.createElement("button");
  ackBtn.setAttribute("data-testid", "acknowledge-action");
  ackBtn.className = "btn btn-primary";
  ackBtn.textContent = "Acknowledge";
  ackBtn.disabled = data.status !== "open";
  ackBtn.addEventListener("click", () => doUpdate(data.id, data.version, { status: "acknowledged" }));
  controls.appendChild(ackBtn);

  const resolveBtn = document.createElement("button");
  resolveBtn.setAttribute("data-testid", "resolve-action");
  resolveBtn.className = "btn btn-danger";
  resolveBtn.textContent = "Resolve";
  resolveBtn.addEventListener("click", () => doUpdate(data.id, data.version, { status: "resolved" }));
  controls.appendChild(resolveBtn);

  detail.appendChild(controls);

  // Timeline
  const timeline = document.createElement("div");
  timeline.setAttribute("data-testid", "timeline");
  const tlTitle = document.createElement("h3");
  tlTitle.textContent = "Audit Timeline";
  timeline.appendChild(tlTitle);

  if (data.events && data.events.length > 0) {
    for (const ev of data.events) {
      const item = document.createElement("div");
      item.className = "timeline-event";
      const time = document.createElement("div");
      time.className = "timeline-time";
      time.textContent = new Date(ev.timestamp * 1000).toLocaleString();
      const body = document.createElement("div");
      const type = document.createElement("div");
      type.className = "timeline-type";
      type.textContent = ev.type;
      body.appendChild(type);
      if (ev.details) {
        const det = document.createElement("div");
        det.className = "timeline-details";
        det.textContent = JSON.stringify(ev.details);
        body.appendChild(det);
      }
      item.appendChild(time);
      item.appendChild(body);
      timeline.appendChild(item);
    }
  } else {
    const empty = document.createElement("p");
    empty.className = "placeholder";
    empty.textContent = "No events.";
    timeline.appendChild(empty);
  }
  detail.appendChild(timeline);
}

async function doUpdate(id, version, changes) {
  const body = { expected_version: version, ...changes };
  const ownerInput = document.querySelector('[data-testid="owner-input"]');
  if (ownerInput && ownerInput.value.trim()) {
    body.owner = ownerInput.value.trim();
  }
  try {
    const response = await fetch("/api/incidents/" + encodeURIComponent(id), {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    const data = await response.json();
    if (response.ok) {
      setFeedback("Incident updated", "success");
      renderDetail(data);
      await refresh();
    } else if (response.status === 409) {
      setFeedback("Version conflict — reload and retry", "error");
      await selectIncident(id);
    } else {
      setFeedback(data.error || "Update failed", "error");
    }
  } catch (err) {
    setFeedback("Update failed: " + err.message, "error");
  }
}

statusFilter.addEventListener("change", () => {
  state.filters.status = statusFilter.value;
  refresh();
});
severityFilter.addEventListener("change", () => {
  state.filters.severity = severityFilter.value;
  refresh();
});

escalateBtn.addEventListener("click", async () => {
  try {
    const response = await fetch("/api/escalations/run", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({}),
    });
    const data = await response.json();
    if (response.ok) {
      setFeedback("Escalated " + data.escalated.length + " incident(s)", "success");
      await refresh();
    } else {
      setFeedback("Escalation failed", "error");
    }
  } catch (err) {
    setFeedback("Escalation failed: " + err.message, "error");
  }
});

function getState() {
  return {
    filters: { ...state.filters },
    selectedIncidentId: state.selectedId,
    incidents: state.incidents,
    feedback: state.feedback,
  };
}

window.incidentOps = {
  refresh,
  selectIncident,
  getState,
};

refresh();
JSEOF
echo "done"

