"""Standard-library HTTP server for the incident operations system."""

from __future__ import annotations

import json
import re
from http.server import BaseHTTPRequestHandler, HTTPServer, ThreadingHTTPServer
from pathlib import Path
from typing import TYPE_CHECKING

from .exceptions import IncidentNotFound, InvalidTransition, VersionConflict
from .models import Incident, IncidentStatus, Severity
from .sqlite_store import SQLiteIncidentStore
from .escalation import EscalationWorker

if TYPE_CHECKING:
    pass

STATIC_DIR = Path(__file__).with_name("static")

_INCIDENT_DETAIL_RE = re.compile(r"^/api/incidents/([^/]+)$")


def json_value(value: object) -> object:
    if hasattr(value, "value"):
        return value.value
    raise TypeError(f"cannot encode {type(value).__name__}")


def incident_to_dict(incident: Incident) -> dict:
    return {
        "id": incident.id,
        "fingerprint": incident.fingerprint,
        "title": incident.title,
        "severity": incident.severity.value,
        "status": incident.status.value,
        "owner": incident.owner,
        "alert_count": incident.alert_count,
        "version": incident.version,
        "escalation_level": incident.escalation_level,
        "created_at": incident.created_at,
        "updated_at": incident.updated_at,
        "sla_deadline": incident.sla_deadline,
    }


def event_to_dict(event) -> dict:
    return {
        "id": event.id,
        "incident_id": event.incident_id,
        "type": event.type,
        "timestamp": event.timestamp,
        "details": event.details,
    }


def incident_detail_to_dict(incident: Incident, events: list) -> dict:
    result = incident_to_dict(incident)
    result["events"] = [event_to_dict(e) for e in events]
    return result


def create_server(
    store: SQLiteIncidentStore,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop."""

    class Handler(BaseHTTPRequestHandler):
        @property
        def _path_only(self) -> str:
            return self.path.split("?", 1)[0]

        def do_GET(self) -> None:
            path = self._path_only
            if path == "/api/incidents":
                return self._handle_list()
            if path == "/api/summary":
                return self._handle_summary()
            match = _INCIDENT_DETAIL_RE.match(path)
            if match:
                return self._handle_detail(match.group(1))
            if path in {"/", "/index.html"}:
                return self._file("index.html", "text/html; charset=utf-8")
            if path == "/app.js":
                return self._file("app.js", "text/javascript; charset=utf-8")
            if path == "/styles.css":
                return self._file("styles.css", "text/css; charset=utf-8")
            self._json(404, {"error": "not found"})

        def do_POST(self) -> None:
            path = self._path_only
            if path == "/api/alerts":
                return self._handle_alert()
            if path == "/api/escalations/run":
                return self._handle_escalation_run()
            self._json(404, {"error": "not found"})

        def do_PATCH(self) -> None:
            path = self._path_only
            match = _INCIDENT_DETAIL_RE.match(path)
            if match:
                return self._handle_patch(match.group(1))
            self._json(404, {"error": "not found"})

        def _handle_list(self) -> None:
            params = self._query_params()
            status = params.get("status")
            severity = params.get("severity")
            owner = params.get("owner")
            try:
                incidents = store.list(status=status, severity=severity, owner=owner)
            except (ValueError, KeyError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, [incident_to_dict(i) for i in incidents])

        def _handle_summary(self) -> None:
            incidents = store.list()
            total = len(incidents)
            by_status: dict[str, int] = {}
            by_severity: dict[str, int] = {}
            for inc in incidents:
                by_status[inc.status.value] = by_status.get(inc.status.value, 0) + 1
                by_severity[inc.severity.value] = (
                    by_severity.get(inc.severity.value, 0) + 1
                )
            self._json(
                200,
                {
                    "total": total,
                    "by_status": by_status,
                    "by_severity": by_severity,
                },
            )

        def _handle_detail(self, incident_id: str) -> None:
            incident = store.get(incident_id)
            if incident is None:
                self._json(404, {"error": "incident not found"})
                return
            events = store.events(incident_id)
            self._json(200, incident_detail_to_dict(incident, events))

        def _handle_alert(self) -> None:
            try:
                payload = self._body()
                fingerprint = payload.get("fingerprint")
                title = payload.get("title")
                severity = payload.get("severity", "P3")
                if not fingerprint:
                    self._json(400, {"error": "fingerprint is required"})
                    return
                if not title:
                    self._json(400, {"error": "title is required"})
                    return
                Severity(severity)
                incident, created = store.ingest_alert(
                    fingerprint=fingerprint,
                    title=title,
                    severity=severity,
                    source=payload.get("source", "unknown"),
                    details=payload.get("details"),
                    idempotency_key=payload.get("idempotency_key"),
                )
                self._json(201 if created else 200, incident_to_dict(incident))
            except (ValueError, KeyError) as exc:
                self._json(400, {"error": str(exc)})
            except json.JSONDecodeError as exc:
                self._json(400, {"error": f"invalid JSON: {exc}"})

        def _handle_patch(self, incident_id: str) -> None:
            try:
                payload = self._body()
                expected_version = payload.get("expected_version")
                if expected_version is None:
                    self._json(400, {"error": "expected_version is required"})
                    return
                expected_version = int(expected_version)
                owner = payload.get("owner")
                status = payload.get("status")
                idempotency_key = payload.get("idempotency_key")
                if status is not None:
                    IncidentStatus(status)
                incident = store.update(
                    incident_id,
                    expected_version,
                    owner=owner,
                    status=status,
                    idempotency_key=idempotency_key,
                )
                events = store.events(incident_id)
                self._json(200, incident_detail_to_dict(incident, events))
            except json.JSONDecodeError as exc:
                self._json(400, {"error": f"invalid JSON: {exc}"})
            except (ValueError, KeyError) as exc:
                self._json(400, {"error": str(exc)})
            except VersionConflict as exc:
                self._json(409, {"error": str(exc)})
            except InvalidTransition as exc:
                self._json(422, {"error": str(exc)})
            except IncidentNotFound:
                self._json(404, {"error": "incident not found"})

        def _handle_escalation_run(self) -> None:
            try:
                payload = self._body()
            except json.JSONDecodeError:
                payload = {}
            worker_id = payload.get("worker_id", "http-worker")
            max_incidents = payload.get("max_incidents")
            if max_incidents is not None:
                max_incidents = int(max_incidents)
            worker = EscalationWorker(store, worker_id)
            results = worker.run_until_idle(max_incidents=max_incidents)
            self._json(200, {"escalated": [incident_to_dict(i) for i in results]})

        def _query_params(self) -> dict[str, str]:
            from urllib.parse import parse_qs, urlparse

            parsed = urlparse(self.path)
            params = parse_qs(parsed.query)
            return {k: v[0] for k, v in params.items() if v}

        def _body(self) -> dict:
            length = int(self.headers.get("Content-Length", "0"))
            if length == 0:
                return {}
            raw = self.rfile.read(length)
            return json.loads(raw)

        def _file(self, name: str, content_type: str) -> None:
            body = (STATIC_DIR / name).read_bytes()
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=json_value).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    srv = ThreadingHTTPServer((host, port), Handler)
    srv.allow_reuse_address = True
    srv.daemon_threads = True
    return srv
